 14→function getInitials(email?: string | null): string {
 15→  if (!email) return "?";
 16→  const name = email.split("@")[0];
 17→  const parts = name.split(/[._-]/);
 18→  if (parts.length >= 2) return (parts[0][0] + parts[1][0]).toUpperCase();
 19→  return name[0]?.toUpperCase() || "?";
 20→}
 21→
 22→function getUserName(email?: string | null): string {
 23→  if (!email) return "User";
 24→  return email.split("@")[0].replace(/[._-]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
 25→}
 26→
 27→const Profile = () => {
 28→  const { user, profile } = useAuth();
 29→  const plan = profile?.plan ?? "free";
 30→  const isPaid = plan !== "free";
 31→
 32→  // Fetch usage stats
 33→  const [stats, setStats] = useState<{ totalJobs: number; totalResumes: number; creditsUsed: number } | null>(null);
 34→  const fetchStats = useCallback(async () => {
 35→    if (!user) return;
 36→    try {
 37→      const [jobsRes, usageRes] = await Promise.all([
 38→        supabase.from("jobs").select("id, resumes(count)").eq("user_id", user.id),
 39→        supabase.from("usage_logs").select("credits_used").eq("user_id", user.id),
 40→      ]);
 41→      const jobs = jobsRes.data ?? [];
 42→      const totalJobs = jobs.length;
 43→      const totalResumes = jobs.reduce((sum: number, j: any) => sum + (j.resumes?.[0]?.count ?? 0), 0);
 44→      const creditsUsed = (usageRes.data ?? []).reduce((sum: number, u: any) => sum + (u.credits_used ?? 0), 0);
 45→      setStats({ totalJobs, totalResumes, creditsUsed });
 46→    } catch {
 47→      toast.error("Failed to load activity stats");
 48→    }
 49→  }, [user]);
 50→  useEffect(() => { fetchStats(); }, [fetchStats]);
 51→
 52→  // Credits
 53→  const sub = profile?.subscription_credits ?? 0;
 54→  const top = profile?.topup_credits ?? 0;
 55→  const bonus = profile?.bonus_credits ?? 0;
 56→  const split = sub + top + bonus;
 57→  const totalCredits = split > 0 ? split : (profile?.credits ?? 0);
 58→
 59→  return (
 60→    <SidebarLayout>
 61→      <main className="w-full max-w-[700px] mx-auto px-4 sm:px-6 lg:px-8 py-8">
