 66→          {/* Account card */}
 67→          <Card>
 68→            <CardContent className="p-6">
 69→              <div className="flex items-center gap-4">
 70→                <div className="h-14 w-14 rounded-full bg-primary text-primary-foreground text-lg font-bold flex items-center justify-center shrink-0">
 71→                  {getInitials(user?.email)}
 72→                </div>
 73→                <div className="min-w-0 flex-1">
 74→                  <h2 className="text-lg font-semibold text-foreground truncate">{getUserName(user?.email)}</h2>
 75→                  <p className="text-sm text-muted-foreground truncate">{user?.email}</p>
 76→                  <div className="flex items-center gap-2 mt-1.5">
 77→                    <Badge variant={isPaid ? "default" : "secondary"} className="text-xs capitalize gap-1">
 78→                      {isPaid && <Crown className="h-3 w-3" />}
 79→                      {plan} plan
 80→                    </Badge>
