 90→                  <Mail className="h-4 w-4 text-muted-foreground" />
 91→                  <div>
 92→                    <p className="text-xs text-muted-foreground">Email</p>
 93→                    <p className="text-foreground truncate">{user?.email}</p>
 94→                  </div>
 95→                </div>
