 97→                  <Calendar className="h-4 w-4 text-muted-foreground" />
 98→                  <div>
 99→                    <p className="text-xs text-muted-foreground">Member since</p>
100→                    <p className="text-foreground">{user?.created_at ? new Date(user.created_at).toLocaleDateString("en-US", { month: "long", year: "numeric" }) : "—"}</p>
101→                  </div>
102→                </div>
