  7→import { Skeleton } from "@/components/ui/skeleton";
  8→import { CreditCard, Receipt } from "lucide-react";
  9→
 10→interface Payment {
 11→  id: string;
 12→  created_at: string;
 13→  amount: number;
 14→  currency: string;
 15→  credits_purchased: number;
 16→  status: string;
 17→  dodo_payment_id: string | null;
 18→  plan_id: string | null;
 19→}
 20→
 21→const PAGE_SIZE = 10;
 22→
 23→const PaymentHistoryCard = () => {
 24→  const { user } = useAuth();
 25→  const [payments, setPayments] = useState<Payment[]>([]);
 26→  const [loading, setLoading] = useState(true);
 27→  const [page, setPage] = useState(0);
 28→  const [hasMore, setHasMore] = useState(false);
 29→  const [loadingMore, setLoadingMore] = useState(false);
 30→
 31→  const fetchPayments = async (pageNum: number, append = false) => {
 32→    if (!user) return;
 33→    if (pageNum === 0) setLoading(true);
 34→    else setLoadingMore(true);
 35→
 36→    const { data } = await supabase
 37→      .from("payments")
 38→      .select("id, created_at, amount, currency, credits_purchased, status, dodo_payment_id, plan_id")
 39→      .eq("user_id", user.id)
 40→      .order("created_at", { ascending: false })
 41→      .range(pageNum * PAGE_SIZE, (pageNum + 1) * PAGE_SIZE - 1);
 42→
 43→    if (data) {
 44→      setHasMore(data.length === PAGE_SIZE);
 45→      setPayments(prev => append ? [...prev, ...data] : data);
 46→    }
 47→    setLoading(false);
 48→    setLoadingMore(false);
 49→  };
 50→
 51→  useEffect(() => {
 52→    fetchPayments(0);
 53→  }, [user]);
 54→
 55→  const loadMore = () => {
 56→    const nextPage = page + 1;
 57→    setPage(nextPage);
 58→    fetchPayments(nextPage, true);
 59→  };
 60→
 61→  const statusVariant = (status: string): "success" | "warning" | "destructive" | "secondary" => {
 62→    switch (status) {
 63→      case "paid": return "success";
 64→      case "created": return "warning";
 65→      case "failed": return "destructive";
 66→      default: return "secondary";
 67→    }
 68→  };
 69→
 70→  const statusLabel = (status: string) => {
 71→    switch (status) {
 72→      case "paid": return "Successful";
 73→      case "created": return "Unpaid";
 74→      case "failed": return "Failed";
 75→      case "dismissed": return "Cancelled";
 76→      default: return "Pending";
 77→    }
 78→  };
 79→
 80→  return (
 81→    <Card className="overflow-hidden">
 82→      <div className="flex items-center gap-3 px-6 pt-5 pb-2">
 83→        <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10">
 84→          <CreditCard className="h-4.5 w-4.5 text-primary" />
 85→        </div>
 86→        <div>
 87→          <h3 className="text-base font-semibold text-foreground">Payment History</h3>
 88→          <p className="text-xs text-muted-foreground">Your recent purchases.</p>
 89→        </div>
 90→      </div>
 91→      <CardContent className="px-6 pt-3 pb-5">
 92→        {loading ? (
 93→          <div className="space-y-3">
 94→            {[...Array(3)].map((_, i) => (
 95→              <Skeleton key={i} className="h-12 w-full rounded-lg" />
 96→            ))}
 97→          </div>
 98→        ) : payments.length === 0 ? (
 99→          <div className="text-center py-10">
100→            <div className="mx-auto mb-3 flex h-12 w-12 items-center justify-center rounded-full bg-accent">
101→              <Receipt className="h-6 w-6 text-muted-foreground/40" />
102→            </div>
103→            <p className="text-sm text-muted-foreground">
104→              No purchases yet. Buy credits to see your payment history here.
105→            </p>
106→          </div>
107→        ) : (
108→          <div className="space-y-1">
109→            {payments.map((p) => (
110→              <div
111→                key={p.id}
112→                className="flex items-center justify-between rounded-lg px-3 py-2.5 hover:bg-accent/50 transition-colors"
113→              >
114→                <div className="min-w-0">
115→                  <p className="text-sm font-medium text-foreground">
116→                    {p.credits_purchased} credits
117→                    <span className="ml-1.5 text-[11px] font-normal text-muted-foreground">
118→                      {p.plan_id ? "Subscription" : "Top-up"}
119→                    </span>
120→                  </p>
121→                  <p className="text-xs text-muted-foreground truncate">
122→                    {new Date(p.created_at).toLocaleDateString("en-US", {
123→                      month: "short", day: "numeric", year: "numeric",
124→                      hour: "2-digit", minute: "2-digit"
125→                    })}
126→                  </p>
127→                </div>
128→                <div className="flex items-center gap-2 shrink-0">
129→                  <span className="text-sm font-semibold tabular-nums text-foreground">
130→                    {p.currency} {(p.amount / 100).toFixed(2)}
131→                  </span>
132→                  <Badge variant={statusVariant(p.status)}>{statusLabel(p.status)}</Badge>
133→                </div>
134→              </div>
135→            ))}
136→          </div>
137→        )}
138→        {!loading && payments.length > 0 && hasMore && (
139→          <div className="pt-3 text-center">
140→            <Button variant="outline" size="sm" onClick={loadMore} disabled={loadingMore}>
141→              {loadingMore ? "Loading…" : "Load more"}
142→            </Button>
143→          </div>
144→        )}
145→      </CardContent>
146→    </Card>
147→  );
148→};
149→
150→export default PaymentHistoryCard;
